refsection.programlisting:
Create Formation Fleet FleetCopy;
Fleet.AllowSharedMembers = true;
FleetCopy.AllowSharedMembers = true;
Fleet.Add = {aSat1, aSat2};
FleetCopy.Add = {aSat1, aSat2};

programlisting.code:
Create Spacecraft aSat1 aSat2

Create Formation aFormation
aFormation.Add = {aSat1, aSat2}

Create Propagator aPropagator

BeginMissionSequence

Propagate aPropagator(aFormation) {aSat1.ElapsedSecs = 12000.0}
